import{_ as e,c as i,o as a,a0 as n}from"./chunks/framework.DKRgXLPU.js";const t=JSON.parse('{"title":"Communication Under Pressure","description":"Master the art of team communication in high-pressure pétanque situations. Learn what to say, when to say it, and how to support teammates effectively.","frontmatter":{"title":"Communication Under Pressure","description":"Master the art of team communication in high-pressure pétanque situations. Learn what to say, when to say it, and how to support teammates effectively."},"headers":[],"relativePath":"fr/blog/team-communication.md","filePath":"fr/blog/team-communication.md"}');const r=e({name:"fr/blog/team-communication.md"},[["render",function(e,t,r,s,l,o){return a(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="communication-sous-pression" tabindex="-1">Communication sous pression <a class="header-anchor" href="#communication-sous-pression" aria-label="Permalink to &quot;Communication sous pression&quot;">​</a></h1><p>À la pétanque, la communication est essentielle au succès ou à l&#39;échec d&#39;une équipe. Les mots justes au bon moment instaurent la confiance et la clarté. À l&#39;inverse, des mots inappropriés – ou le silence quand la communication est nécessaire – peuvent déstabiliser même les équipes les plus performantes.</p><h2 id="pourquoi-la-communication-est-importante" tabindex="-1">Pourquoi la communication est importante <a class="header-anchor" href="#pourquoi-la-communication-est-importante" aria-label="Permalink to &quot;Pourquoi la communication est importante&quot;">​</a></h2><p>Les équipes de pétanque sont confrontées à des défis de communication uniques :</p><ul><li>Des décisions doivent être prises rapidement.</li><li>La pression influence notre façon de parler et d&#39;écouter.</li><li>Les signaux non verbaux sont visibles pour les adversaires.</li><li>La performance individuelle influence la dynamique d&#39;équipe</li></ul><p>Une communication efficace permet de créer :</p><ul><li>Compréhension partagée de la stratégie</li><li>Soutien mutuel et confiance</li><li>Prise de décision rapide et claire</li><li>Résilience face aux moments difficiles</li></ul><h2 id="les-principes-de-la-communication" tabindex="-1">Les principes de la communication <a class="header-anchor" href="#les-principes-de-la-communication" aria-label="Permalink to &quot;Les principes de la communication&quot;">​</a></h2><h3 id="_1-la-clarte-prime-sur-la-quantite" tabindex="-1">1. La clarté prime sur la quantité <a class="header-anchor" href="#_1-la-clarte-prime-sur-la-quantite" aria-label="Permalink to &quot;1. La clarté prime sur la quantité&quot;">​</a></h3><p>Sous pression, la concision est de mise. Une communication claire et concise vaut mieux que de longues discussions.</p><p><strong>Au lieu de :</strong> « Je pense qu&#39;on devrait peut-être essayer de montrer du doigt ici, mais je ne suis pas sûr, qu&#39;en penses-tu ? Le terrain a l&#39;air difficile... »</p><p><strong>Dites :</strong> « Je vais montrer le côté gauche. Le terrain est meilleur là-bas. »</p><h3 id="_2-cadrage-positif" tabindex="-1">2. Cadrage positif <a class="header-anchor" href="#_2-cadrage-positif" aria-label="Permalink to &quot;2. Cadrage positif&quot;">​</a></h3><p>Cadrer les communications de manière constructive :</p><p><strong>Au lieu de :</strong> « Ne ratez pas ça ! » <strong>Dites :</strong> « Tu peux le faire — fais confiance à ton lancer »</p><p><strong>Au lieu de :</strong> « C&#39;était terrible » <strong>Dites :</strong> « On passe à autre chose, au suivant ! »</p><h3 id="_3-focus-sur-le-present" tabindex="-1">3. Focus sur le présent <a class="header-anchor" href="#_3-focus-sur-le-present" aria-label="Permalink to &quot;3. Focus sur le présent&quot;">​</a></h3><p>Concentrez votre communication sur l&#39;avenir, et non sur le passé :</p><p><strong>Au lieu de :</strong> « Pourquoi l&#39;as-tu jeté là ? » <strong>Dites :</strong> « Bon, quelle est notre meilleure option maintenant ? »</p><h3 id="_4-langage-de-propriete" tabindex="-1">4. Langage de propriété <a class="header-anchor" href="#_4-langage-de-propriete" aria-label="Permalink to &quot;4. Langage de propriété&quot;">​</a></h3><p>Utilisez le « je » pour vos propres actions et le « nous » pour les situations d&#39;équipe :</p><ul><li>« Je vais tenter ma chance. »</li><li>«Nous devons protéger ce point.»</li><li>«Je pense que nous devrions...»</li></ul><h2 id="que-communiquer" tabindex="-1">Que communiquer <a class="header-anchor" href="#que-communiquer" aria-label="Permalink to &quot;Que communiquer&quot;">​</a></h2><h3 id="avant-chaque-extremite" tabindex="-1">Avant chaque extrémité <a class="header-anchor" href="#avant-chaque-extremite" aria-label="Permalink to &quot;Avant chaque extrémité&quot;">​</a></h3><ul><li><strong>Discussion stratégique</strong> : Bref alignement sur l’approche</li><li><strong>Clarté des rôles</strong> : Qui fait quoi ?</li><li><strong>Observations sur le terrain</strong> : Conditions pertinentes</li></ul><h3 id="pendant-le-jeu" tabindex="-1">Pendant le jeu <a class="header-anchor" href="#pendant-le-jeu" aria-label="Permalink to &quot;Pendant le jeu&quot;">​</a></h3><ul><li><strong>Décisions</strong> : Énoncé clair de l’action envisagée</li><li><strong>Soutien</strong> : Encouragements avant les lancers</li><li><strong>Informations</strong> : Observations pertinentes concernant le terrain ou les adversaires</li></ul><h3 id="apres-les-lancers" tabindex="-1">Après les lancers <a class="header-anchor" href="#apres-les-lancers" aria-label="Permalink to &quot;Après les lancers&quot;">​</a></h3><ul><li><strong>Remerciements</strong> : Brève reconnaissance (positive ou négative)</li><li><strong>Ajustements</strong> : Tout changement stratégique nécessaire</li><li><strong>Réinitialisation</strong> : Aider un coéquipier à se recentrer</li></ul><h2 id="ce-qu-39-il-ne-faut-pas-communiquer" tabindex="-1">Ce qu&#39;il ne faut PAS communiquer <a class="header-anchor" href="#ce-qu-39-il-ne-faut-pas-communiquer" aria-label="Permalink to &quot;Ce qu&amp;#39;il ne faut PAS communiquer&quot;">​</a></h2><h3 id="a-eviter-lors-des-moments-de-pression" tabindex="-1">À éviter lors des moments de pression <a class="header-anchor" href="#a-eviter-lors-des-moments-de-pression" aria-label="Permalink to &quot;À éviter lors des moments de pression&quot;">​</a></h3><ul><li>Instructions techniques (« Gardez votre coude à l&#39;intérieur »)</li><li>Critiques des lancers passés</li><li>Expressions de frustration</li><li>Doute sur les capacités du coéquipier</li><li>Analyse excessive</li></ul><h3 id="a-eviter-en-general" tabindex="-1">À éviter en général <a class="header-anchor" href="#a-eviter-en-general" aria-label="Permalink to &quot;À éviter en général&quot;">​</a></h3><ul><li>Langage du blâme</li><li>Sarcasme ou agression passive</li><li>Comparaisons avec d&#39;autres joueurs</li><li>Prédictions d&#39;échec</li></ul><h2 id="communication-non-verbale" tabindex="-1">Communication non verbale <a class="header-anchor" href="#communication-non-verbale" aria-label="Permalink to &quot;Communication non verbale&quot;">​</a></h2><p>Votre langage corporel en dit long :</p><h3 id="signaux-positifs" tabindex="-1">Signaux positifs <a class="header-anchor" href="#signaux-positifs" aria-label="Permalink to &quot;Signaux positifs&quot;">​</a></h3><ul><li>contact visuel avec les coéquipiers</li><li>Posture ouverte et détendue</li><li>Hochements de tête et reconnaissance</li><li>Mouvements calmes et réguliers</li></ul><h3 id="signaux-negatifs-a-eviter" tabindex="-1">Signaux négatifs (à éviter) <a class="header-anchor" href="#signaux-negatifs-a-eviter" aria-label="Permalink to &quot;Signaux négatifs (à éviter)&quot;">​</a></h3><ul><li>Lever les yeux au ciel ou soupirer</li><li>Se détourner de ses coéquipiers</li><li>Bras croisés ou posture fermée</li><li>Frustration visible</li></ul><h3 id="coequipiers-de-lecture" tabindex="-1">Coéquipiers de lecture <a class="header-anchor" href="#coequipiers-de-lecture" aria-label="Permalink to &quot;Coéquipiers de lecture&quot;">​</a></h3><p>Apprenez à reconnaître les besoins de vos coéquipiers :</p><ul><li><strong>Espace</strong> : Ils traitent les données, ne les interrompez pas.</li><li><strong>Soutien</strong> : Ils sont en difficulté, offrez-leur des encouragements.</li><li><strong>Information</strong> : Leurs propos sont incertains, veuillez apporter des précisions.</li><li><strong>Énergie</strong> : Elles sont plates, elles apportent de l&#39;enthousiasme</li></ul><h2 id="roles-de-communication" tabindex="-1">Rôles de communication <a class="header-anchor" href="#roles-de-communication" aria-label="Permalink to &quot;Rôles de communication&quot;">​</a></h2><h3 id="le-pointeur" tabindex="-1">Le Pointeur <a class="header-anchor" href="#le-pointeur" aria-label="Permalink to &quot;Le Pointeur&quot;">​</a></h3><ul><li>Faites part de votre analyse du terrain.</li><li>Indiquez clairement l&#39;emplacement prévu.</li><li>Demandez un avis en cas de doute</li></ul><h3 id="le-tireur" tabindex="-1">Le tireur <a class="header-anchor" href="#le-tireur" aria-label="Permalink to &quot;Le tireur&quot;">​</a></h3><ul><li>Confirmer la sélection de la cible</li><li>Communiquer le niveau de confiance</li><li>Demander des informations sur les angles</li></ul><h3 id="le-milieu-capitaine" tabindex="-1">Le Milieu/Capitaine <a class="header-anchor" href="#le-milieu-capitaine" aria-label="Permalink to &quot;Le Milieu/Capitaine&quot;">​</a></h3><ul><li>Faciliter les discussions d&#39;équipe</li><li>Prendre les décisions finales lorsque cela est nécessaire</li><li>Gérer l&#39;énergie et la concentration de l&#39;équipe</li></ul><h2 id="situations-de-pression" tabindex="-1">Situations de pression <a class="header-anchor" href="#situations-de-pression" aria-label="Permalink to &quot;Situations de pression&quot;">​</a></h2><h3 id="quand-derriere" tabindex="-1">Quand derrière <a class="header-anchor" href="#quand-derriere" aria-label="Permalink to &quot;Quand derrière&quot;">​</a></h3><ul><li>Restez concentré sur les solutions</li><li>Maintenez une énergie positive</li><li>Évitez les reproches et la frustration.</li><li>Célébrez les petites victoires</li></ul><h3 id="quand-en-avance" tabindex="-1">Quand en avance <a class="header-anchor" href="#quand-en-avance" aria-label="Permalink to &quot;Quand en avance&quot;">​</a></h3><ul><li>Restez concentré, évitez la complaisance</li><li>Maintenez une communication cohérente</li><li>Ne changez pas ce qui fonctionne</li></ul><h3 id="point-de-match-le-leur" tabindex="-1">Point de match (le leur) <a class="header-anchor" href="#point-de-match-le-leur" aria-label="Permalink to &quot;Point de match (le leur)&quot;">​</a></h3><ul><li>Reconnaissez brièvement la pression.</li><li>Concentrez-vous sur le processus</li><li>Soutenez-vous mutuellement de manière visible</li></ul><h3 id="pointe-de-match-la-notre" tabindex="-1">Pointe de match (la nôtre) <a class="header-anchor" href="#pointe-de-match-la-notre" aria-label="Permalink to &quot;Pointe de match (la nôtre)&quot;">​</a></h3><ul><li>Restez calme et concentré</li><li>Évitez les célébrations prématurées</li><li>Exécuter normalement</li></ul><h2 id="developper-ses-competences-en-communication" tabindex="-1">Développer ses compétences en communication <a class="header-anchor" href="#developper-ses-competences-en-communication" aria-label="Permalink to &quot;Développer ses compétences en communication&quot;">​</a></h2><h3 id="en-pratique" tabindex="-1">En pratique <a class="header-anchor" href="#en-pratique" aria-label="Permalink to &quot;En pratique&quot;">​</a></h3><ul><li>Pratiquez la communication pendant l&#39;entraînement</li><li>Donner et recevoir des commentaires sur la communication</li><li>Expérimentez différentes approches</li></ul><h3 id="accords-d-39-equipe" tabindex="-1">Accords d&#39;équipe <a class="header-anchor" href="#accords-d-39-equipe" aria-label="Permalink to &quot;Accords d&amp;#39;équipe&quot;">​</a></h3><p>Établir des normes d&#39;équipe :</p><ul><li>Comment nous gérons les désaccords</li><li>À quoi ressemble le soutien</li><li>Quand parler et quand se taire</li></ul><h3 id="analyse-d-39-apres-match" tabindex="-1">Analyse d&#39;après-match <a class="header-anchor" href="#analyse-d-39-apres-match" aria-label="Permalink to &quot;Analyse d&amp;#39;après-match&quot;">​</a></h3><p>Discuter de la communication :</p><ul><li>Qu&#39;est-ce qui a bien fonctionné ?</li><li>Qu&#39;est-ce qui pourrait être amélioré ?</li><li>Des malentendus à clarifier ?</li></ul><h2 id="quand-la-communication-se-rompt" tabindex="-1">Quand la communication se rompt <a class="header-anchor" href="#quand-la-communication-se-rompt" aria-label="Permalink to &quot;Quand la communication se rompt&quot;">​</a></h2><h3 id="dans-l-39-instant" tabindex="-1">Dans l&#39;instant <a class="header-anchor" href="#dans-l-39-instant" aria-label="Permalink to &quot;Dans l&amp;#39;instant&quot;">​</a></h3><ol><li>Respirez</li><li>Repartons sur une simple affirmation : « Concentrons-nous sur ce lancer. »</li><li>Retour aux fondamentaux : clair, positif, présent</li></ol><h3 id="apres-le-match" tabindex="-1">Après le match <a class="header-anchor" href="#apres-le-match" aria-label="Permalink to &quot;Après le match&quot;">​</a></h3><ul><li>Réglez les problèmes calmement</li><li>Concentrez-vous sur les comportements, pas sur les personnalités.</li><li>Convenir des améliorations</li><li>Avancer ensemble</li></ul><h2 id="le-soutien-silencieux" tabindex="-1">Le soutien silencieux <a class="header-anchor" href="#le-soutien-silencieux" aria-label="Permalink to &quot;Le soutien silencieux&quot;">​</a></h2><p>Parfois, la meilleure communication est la présence :</p><ul><li>Soutenir un coéquipier en difficulté</li><li>Une main sur l&#39;épaule</li><li>Un signe de confiance</li><li>Le simple fait d&#39;être là</li></ul><p>Les mots ne sont pas toujours nécessaires. Le lien, lui, l&#39;est.</p><hr><p>| <em>En lien avec : <a href="/en/education/team-player/">Dynamique d&#39;équipe</a> | <a href="/en/education/team-player/communication">Communication</a> | <a href="/en/education/mental-strength/handling-pressure">Gérer la pression</a></em> |</p>',79)])])}]]);export{t as __pageData,r as default};
